Íme a teljes, azonnal futtatható Jade meta‑modell rendszer két fájlja: egy egyszálú, standard könyvtáras Python backend, amely Exa keresést és Cerebras valamint xAI Grok chat‑completions hívásokat végez, valamint egy PWA frontend Apple‑stílusú UI‑val és offline támogatással; a modellnevek elrejtve maradnak, a kimenet mindenhol Jade néven jelenik meg.[1][2][3][4][5]
A backend automatikusan többkörös kutatást tervez, Exa‑val akár nagy tömegű forrást gyűjt, párhuzamosan tömörít, majd két modell válaszait konszenzussá egyesíti; környezetváltozókon keresztül konfigurálható: EXA_API_KEY, CEREBRAS_API_KEY, XAI_API_KEY, JADE_MAX_RESULTS, JADE_MAX_STEPS, JADE_LIVECRAWL, és PORT.[2][3][4][5][1]

### backend.py
```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import os, sys, json, ssl, time, threading, traceback
from urllib import request as urlrequest
from urllib.parse import urlencode
from http.server import BaseHTTPRequestHandler, HTTPServer

APP_NAME = "Jade"
FRONTEND_FILE = "frontend.html"

# ----------- Config ----------- #
EXA_API_KEY = os.environ.get("EXA_API_KEY", "").strip()
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY", "").strip()
XAI_API_KEY = os.environ.get("XAI_API_KEY", "").strip()
PORT = int(os.environ.get("PORT", "8000"))
DEFAULT_MAX_RESULTS = int(os.environ.get("JADE_MAX_RESULTS", "25"))
DEFAULT_MAX_STEPS = int(os.environ.get("JADE_MAX_STEPS", "4"))
DEFAULT_LIVECRAWL = os.environ.get("JADE_LIVECRAWL", "preferred")  # always|preferred|fallback|never

CTX = ssl.create_default_context()

def _http_post_json(url: str, headers: dict, payload: dict, timeout: int = 60):
    data = json.dumps(payload).encode("utf-8")
    req = urlrequest.Request(url, data=data, headers=headers, method="POST")
    with urlrequest.urlopen(req, context=CTX, timeout=timeout) as resp:
        body = resp.read().decode("utf-8")
        return resp.getcode(), json.loads(body), dict(resp.headers)

def _http_get(url: str, headers: dict = None, timeout: int = 60):
    req = urlrequest.Request(url, headers=headers or {}, method="GET")
    with urlrequest.urlopen(req, context=CTX, timeout=timeout) as resp:
        body = resp.read()
        return resp.getcode(), body.decode("utf-8"), dict(resp.headers)

# ----------- Exa helpers ----------- #
EXA_BASE = ""

def exa_search_and_contents(query: str, num_results: int = DEFAULT_MAX_RESULTS, livecrawl: str = DEFAULT_LIVECRAWL):
    if not EXA_API_KEY:
        raise RuntimeError("Missing EXA_API_KEY")
    headers = {
        "Content-Type": "application/json",
        "x-api-key": EXA_API_KEY
    }

    # Try combined endpoint first
    payload = {
        "query": query,
        "type": "auto",
        "numResults": max(1, min(100, int(num_results))),
        "livecrawl": livecrawl,
        "text": True,
        "highlights": True,
        "summary": {"query": "Summarize key facts in 2 sentences."},
        "textContentsOptions": {"maxCharacters": 4000}
    }
    try:
        code, data, _ = _http_post_json(f"{EXA_BASE}/search_and_contents", headers, payload, timeout=90)
        if code == 200 and "results" in data:
            return data["results"]
    except Exception:
        pass

    # Fallback: /search then /contents
    search_payload = {
        "query": query,
        "type": "auto",
        "numResults": max(1, min(100, int(num_results))),
    }
    code, search_data, _ = _http_post_json(f"{EXA_BASE}/search", headers, search_payload, timeout=45)
    if code != 200 or "results" not in search_data:
        raise RuntimeError(f"Exa search failed: {code}: {search_data}")
    ids = []
    urls = []
    for r in search_data.get("results", []):
        if "id" in r:
            ids.append(r["id"])
        elif "url" in r:
            urls.append(r["url"])
    contents_payload = {}
    if ids:
        contents_payload["ids"] = ids
    if urls:
        contents_payload["urls"] = urls
    contents_payload["text"] = True
    contents_payload["highlights"] = True
    contents_payload["livecrawl"] = livecrawl
    contents_payload["summary"] = {"query": "Summarize key facts in 2 sentences."}
    contents_payload["textContentsOptions"] = {"maxCharacters": 4000}
    code, contents_data, _ = _http_post_json(f"{EXA_BASE}/contents", headers, contents_payload, timeout=90)
    if code != 200 or "results" not in contents_data:
        # As last resort, return bare search results
        return search_data.get("results", [])
    return contents_data.get("results", [])

# ----------- LLM helpers (names hidden, branded as Jade) ----------- #
CEREBRAS_CHAT_URL = ""
XAI_CHAT_URL = ""

def cerebras_chat(messages, model="gpt-oss-120b", temperature=0.3, max_tokens=1024):
    if not CEREBRAS_API_KEY:
        raise RuntimeError("Missing CEREBRAS_API_KEY")
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {CEREBRAS_API_KEY}",
    }
    payload = {
        "model": model,
        "messages": messages,
        "temperature": float(temperature),
        "max_tokens": int(max_tokens),
    }
    code, data, _ = _http_post_json(CEREBRAS_CHAT_URL, headers, payload, timeout=120)
    if code != 200:
        raise RuntimeError(f"Cerebras error: {code}: {data}")
    return data.get("choices", [{}])[0].get("message", {}).get("content", "")

def xai_chat(messages, model="grok-4-fast-reasoning", temperature=0.3, max_tokens=1024):
    if not XAI_API_KEY:
        raise RuntimeError("Missing XAI_API_KEY")
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {XAI_API_KEY}",
    }
    payload = {
        "model": model,
        "messages": messages,
        "temperature": float(temperature),
        "max_tokens": int(max_tokens),
    }
    code, data, _ = _http_post_json(XAI_CHAT_URL, headers, payload, timeout=120)
    if code != 200:
        raise RuntimeError(f"xAI error: {code}: {data}")
    return data.get("choices", [{}])[0].get("message", {}).get("content", "")

# ----------- Orchestrator ----------- #

SYSTEM_PLANNER = (
    "Act as an elite research planner for the Jade meta‑model. "
    "Generate a concise list of diverse, targeted web search queries (8–15) that together will comprehensively resolve the user’s goal. "
    "Cover terminology variants, adjacent concepts, stakeholders, evaluation criteria, and common pitfalls. "
    "Return a pure JSON array of strings, no prose."
)

SYSTEM_SYNTH = (
    "You are Jade, a single, unified expert model. "
    "Write a rigorous answer grounded only in the provided source snippets. "
    "Cite inline with bracketed numeric indices referring to the provided sources list (e.g., [1], [2]). "
    "Be decisive, note uncertainties, propose next steps, and add a short checklist. "
    "Do not reveal internal model names or providers."
)

def generate_queries_with_xai(user_prompt: str):
    try:
        content = xai_chat(
            [
                {"role": "system", "content": SYSTEM_PLANNER},
                {"role": "user", "content": user_prompt}
            ],
            model="grok-4-fast-reasoning",
            temperature=0.2,
            max_tokens=800
        )
        arr = json.loads(content)
        return [q for q in arr if isinstance(q, str)][:20]
    except Exception:
        # Minimal fallback
        base = user_prompt.strip()
        seeds = [
            base,
            f"{base} latest developments",
            f"{base} detailed technical report",
            f"{base} benchmarks comparison",
            f"{base} real-world case studies",
            f"{base} risks limitations",
            f"{base} pricing and licensing",
            f"{base} tutorials and implementation",
        ]
        return seeds

def summarize_chunk_with_cerebras(text: str, url: str, title: str):
    prompt = (
        f"Source: {title} ({url})\n\n"
        f"Extract key facts, numbers, claims, and uncertainties in bullet points (max 1200 chars). "
        f"Return compact, factual notes."
    )
    return cerebras_chat(
        [{"role": "system", "content": "You are a precise scientific summarizer."},
         {"role": "user", "content": prompt}],
        model="gpt-oss-120b",
        temperature=0.1,
        max_tokens=600
    )

def consensus_synthesis(summaries: list, sources_meta: list, user_prompt: str):
    # First candidate with Cerebras
    context = []
    for i, s in enumerate(summaries, 1):
        context.append(f"[{i}] {s}")
    ctx_text = "\n".join(context)[:240000]  # safety cap
    sources_listing = "\n".join([f"[{i+1}] {m.get('title','')} - {m.get('url','')}" for i, m in enumerate(sources_meta)])
    messages = [
        {"role": "system", "content": SYSTEM_SYNTH},
        {"role": "user", "content": f"Question: {user_prompt}\n\nSources:\n{sources_listing}\n\nSnippets:\n{ctx_text}\n\nWrite the final answer as Jade."}
    ]
    try:
        a = cerebras_chat(messages, model="gpt-oss-120b", temperature=0.2, max_tokens=1200)
    except Exception:
        a = ""
    try:
        b = xai_chat(messages, model="grok-4-0709", temperature=0.2, max_tokens=1200)
    except Exception:
        b = ""
    # Arbiter (xAI fast) to merge
    arbiter_msgs = [
        {"role": "system", "content": "Merge two candidate answers into one superior, strictly evidence‑grounded response with numbered source citations."},
        {"role": "user", "content": f"Answer A:\n{a}\n\nAnswer B:\n{b}\n\nProduce a single best answer as Jade; do not mention A/B or provider names."}
    ]
    try:
        merged = xai_chat(arbiter_msgs, model="grok-4-fast-reasoning", temperature=0.2, max_tokens=1400)
        final = merged.strip() or a or b
    except Exception:
        final = a or b or "Insufficient data to answer."
    return final

def research_pipeline(user_prompt: str, max_steps: int = DEFAULT_MAX_STEPS, max_results: int = DEFAULT_MAX_RESULTS, livecrawl: str = DEFAULT_LIVECRAWL):
    queries = generate_queries_with_xai(user_prompt)
    collected = []
    seen_urls = set()
    step = 0
    for q in queries:
        if step >= max_steps:
            break
        try:
            results = exa_search_and_contents(q, num_results=max_results, livecrawl=livecrawl)
            for r in results:
                url = r.get("url") or r.get("id")
                if not url or url in seen_urls:
                    continue
                seen_urls.add(url)
                collected.append({
                    "url": url,
                    "title": r.get("title") or "",
                    "text": (r.get("text") or "")[:12000],
                    "highlights": r.get("highlights") or [],
                    "publishedDate": r.get("publishedDate") or ""
                })
            step += 1
        except Exception:
            continue
    if not collected:
        raise RuntimeError("No sources collected")
    # Summarize in parallel
    summaries = [""] * len(collected)
    def worker(idx, item):
        try:
            base_text = item["text"] or " ".join(item.get("highlights") or []) or ""
            if not base_text:
                summaries[idx] = f"{item['title']} — no extractable text."
                return
            summaries[idx] = summarize_chunk_with_cerebras(base_text[:8000], item["url"], item["title"])
        except Exception:
            summaries[idx] = f"{item['title']} — summarization failed."
    threads = []
    for i, it in enumerate(collected):
        t = threading.Thread(target=worker, args=(i, it), daemon=True)
        t.start()
        threads.append(t)
    for t in threads:
        t.join(timeout=120)
    # Synthesis
    answer = consensus_synthesis(summaries, collected, user_prompt)
    return answer, collected

# ----------- HTTP Handler ----------- #

APPLE_MANIFEST = {
    "name": "Jade",
    "short_name": "Jade",
    "start_url": "/",
    "display": "standalone",
    "background_color": "#000000",
    "theme_color": "#000000",
    "icons": []
}

SW_JS = """
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open('jade-cache-v1').then(c => c.addAll(['/'])));
});
self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(resp => resp || fetch(e.request).catch(() => new Response('Offline', {status: 200})))
  );
});
"""

class Handler(BaseHTTPRequestHandler):
    def _set_headers(self, code=200, ctype="text/html; charset=utf-8"):
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Cache-Control", "no-store")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization")
        self.end_headers()

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization")
        self.end_headers()

    def do_GET(self):
        path = self.path.split("?")[0]
        if path == "/":
            try:
                with open(FRONTEND_FILE, "rb") as f:
                    content = f.read()
                self._set_headers(200, "text/html; charset=utf-8")
                self.wfile.write(content)
            except Exception:
                self._set_headers(200, "text/plain; charset=utf-8")
                self.wfile.write(b"Frontend not found. Place frontend.html alongside backend.py")
            return
        if path == "/sw.js":
            self._set_headers(200, "application/javascript; charset=utf-8")
            self.wfile.write(SW_JS.encode("utf-8"))
            return
        if path in ("/manifest.webmanifest", "/manifest.json"):
            self._set_headers(200, "application/manifest+json; charset=utf-8")
            self.wfile.write(json.dumps(APPLE_MANIFEST).encode("utf-8"))
            return
        self._set_headers(404, "text/plain; charset=utf-8")
        self.wfile.write(b"Not found")

    def do_POST(self):
        path = self.path.split("?")[0]
        if path != "/api/jade":
            self._set_headers(404, "application/json; charset=utf-8")
            self.wfile.write(json.dumps({"error":"not_found"}).encode("utf-8"))
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
            raw = self.rfile.read(length) if length > 0 else b"{}"
            data = json.loads(raw.decode("utf-8"))
            prompt = data.get("prompt") or ""
            max_steps = int(data.get("max_steps") or DEFAULT_MAX_STEPS)
            max_results = int(data.get("max_results") or DEFAULT_MAX_RESULTS)
            livecrawl = data.get("livecrawl") or DEFAULT_LIVECRAWL
            if not prompt.strip():
                raise ValueError("Empty prompt")
            answer, sources = research_pipeline(prompt.strip(), max_steps=max_steps, max_results=max_results, livecrawl=livecrawl)
            resp = {
                "model": APP_NAME,
                "answer": answer,
                "sources": [{"title": s["title"], "url": s["url"], "publishedDate": s["publishedDate"]} for s in sources]
            }
            self._set_headers(200, "application/json; charset=utf-8")
            self.wfile.write(json.dumps(resp).encode("utf-8"))
        except Exception as e:
            err = {"error": str(e), "trace": traceback.format_exc()[:4000]}
            self._set_headers(200, "application/json; charset=utf-8")
            self.wfile.write(json.dumps({"model": APP_NAME, "answer": "Hiba tortent a feldolgozas soran.", "debug": err}).encode("utf-8"))

def run():
    server = HTTPServer(("", PORT), Handler)
    print(f"{APP_NAME} backend running on port {PORT}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

if __name__ == "__main__":
    run()
```

